import 'package:flutter/material.dart';import 'package:sqflite/sqflite.dart';import '../../data/local_database.dart';import '../backup/backup_screen.dart';
class SettingsScreen extends StatefulWidget{const SettingsScreen({super.key});@override State<SettingsScreen> createState()=>_SettingsScreenState();}
class _SettingsScreenState extends State<SettingsScreen>{final name=TextEditingController();bool stock=false;bool loaded=false;
Future<void> init()async{final db=await LocalDatabase.instance.database;final s=(await db.query('store_settings',where:'id=1')).first;name.text=s['store_name'] as String;stock=await LocalDatabase.instance.stockEnabled();if(mounted)setState(()=>loaded=true);}
Future<void> password()async{final p=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('تغيير كلمة المرور'),content:TextField(controller:p,obscureText:true,decoration:const InputDecoration(labelText:'كلمة المرور الجديدة (6 أحرف على الأقل)')),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('تغيير'))]));if(ok==true&&p.text.length>=6){await LocalDatabase.instance.changePassword(p.text);if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تم تغيير كلمة المرور')));}}
@override Widget build(BuildContext c){if(!loaded)init();return Scaffold(appBar:AppBar(title:const Text('الإعدادات')),body:!loaded?const Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.all(16),children:[TextField(controller:name,decoration:const InputDecoration(labelText:'اسم المحل')),SwitchListTile(value:stock,title:const Text('تفعيل إدارة المخزون'),onChanged:(v)async{setState(()=>stock=v);await(await LocalDatabase.instance.database).insert('app_settings',{'key':'stock_enabled','value':v.toString()},conflictAlgorithm:ConflictAlgorithm.replace);}),FilledButton(onPressed:()async{await(await LocalDatabase.instance.database).update('store_settings',{'store_name':name.text},where:'id=1');if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('تم حفظ اسم المحل')));},child:const Text('حفظ بيانات المحل')),ListTile(leading:const Icon(Icons.lock),title:const Text('تغيير كلمة المرور'),onTap:password),ListTile(leading:const Icon(Icons.backup),title:const Text('النسخ الاحتياطي والاستعادة'),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>const BackupScreen()))) ]));}
}
